const question = (
  id: string,
  layer: Layer,
  domain: string,
  prompt: string,
  effects: Record<string, number>,
  context: string,
  refs: readonly string[],
  targetNodeIds: readonly string[] = [],
): Question => {
  const hasAcademicSource = refs.some((sourceRef) => SOURCES.find((source) => source.id === sourceRef)?.role === "ideology-research");
  const sourceRefsWithAcademicBasis = hasAcademicSource ? refs : [...refs, academicSourceForQuestion(id, layer, domain)];
  return {
    id,
    layer,
    domain,
    prompt,
    context,
    effects,
    sourceType: "original",
    sourceRefs: sourceRefsWithAcademicBasis,
    ...(targetNodeIds.length > 0 ? { targetNodeIds } : {}),
    version: 1,
  };
};

