const layerFacetIds = (layer: Layer): readonly string[] => FACETS.filter((facet) => facet.layer === layer).map((facet) => facet.id);

const vector = (layer: Layer, values: Record<string, number>): Readonly<Record<string, number>> =>
  Object.fromEntries(layerFacetIds(layer).map((id) => [id, values[id] ?? 0]));

