const anchor = (
  id: string,
  label: string,
  family: string,
  summary: string,
  descriptive: Record<string, number>,
  normative: Record<string, number>,
  prescriptive: Record<string, number>,
  note: string,
  ontologyNodeId = id,
): IdeologyAnchor => ({
  id,
  label,
  family,
  ontologyNodeId,
  summary,
  profiles: {
    descriptive: vector("descriptive", descriptive),
    normative: vector("normative", normative),
    prescriptive: vector("prescriptive", prescriptive),
  },
  sourceType: "editorial",
  sourceRefs: [...sourceRefs("source-8values", "source-leftvalues"), academicSourceForAnchor(id)],
  note,
  version: 1,
});

